import products from './products.json' with { type: 'json' };

export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search the product inventory by name. Returns matching products, limited to a maximum number of results.',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Case-insensitive substring to match against product names.' },
          limit: { type: 'integer', minimum: 1, maximum: 10, description: 'Maximum number of results to return (1-10). Defaults to 10.' }
        },
        required: ['query']
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'inventory_search') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Arguments must be an object');
  }

  const { query, limit } = args;

  if (typeof query !== 'string') {
    throw new Error('query must be a string');
  }

  let effectiveLimit = 10;
  if (limit !== undefined) {
    if (typeof limit !== 'number' || !Number.isInteger(limit)) {
      throw new Error('limit must be an integer');
    }
    if (limit < 1 || limit > 10) {
      throw new Error('limit must be between 1 and 10');
    }
    effectiveLimit = limit;
  }

  const needle = query.toLowerCase();
  const matches = products
    .filter(p => typeof p.name === 'string' && p.name.toLowerCase().includes(needle))
    .slice(0, effectiveLimit);

  const text = matches.length === 0
    ? `No products found matching "${query}".`
    : matches.map(p => `${p.id}: ${p.name}`).join('\n');

  return {
    content: [{ type: 'text', text }]
  };
}

